class Solution:
    def removeDuplicateLetters(self, s: str) -> str:
        def solve(t):
            if not t:
                return ""
            need = set(t)
            for ch in sorted(need):
                pos = t.index(ch)
                if set(t[pos:]) == need:
                    return ch + solve(t[pos + 1:].replace(ch, ""))
            return ""
        return solve(s)

solutions.better:
class Solution:
    def removeDuplicateLetters(self, s):
        from collections import Counter
        remaining = Counter(s)
        stack = []
        used = set()
        for ch in s:
            remaining[ch] -= 1
            if ch in used:
                continue
            while stack and ch < stack[-1] and remaining[stack[-1]] > 0:
                used.remove(stack.pop())
            stack.append(ch)
            used.add(ch)
        return ''.join(stack)

